/**
 * Geography constants for Forest State (London, ON) and Mustang City (Western campus).
 * Coordinates are [lng, lat]. The London boundary is a hand-simplified outline of the
 * city's municipal extent — good enough for fog + % explored; swap for open data later.
 */

export type LngLat = [number, number];

export const LONDON_BOUNDARY: LngLat[] = [
  [-81.395, 43.012],
  [-81.37, 43.055],
  [-81.31, 43.078],
  [-81.235, 43.083],
  [-81.17, 43.068],
  [-81.12, 43.04],
  [-81.105, 42.99],
  [-81.13, 42.935],
  [-81.2, 42.905],
  [-81.29, 42.9],
  [-81.355, 42.925],
  [-81.39, 42.965],
  [-81.395, 43.012],
];

export const LONDON_CENTER: LngLat = [-81.2453, 42.9849];

/** Western University main campus. */
export const CAMPUS_CENTER: LngLat = [-81.2737, 43.0096];

export const CAMPUS_BBOX = {
  west: -81.2875,
  south: 43.0015,
  east: -81.2625,
  north: 43.0175,
};

export const CAMPUS_POLYGON: LngLat[] = [
  [CAMPUS_BBOX.west, CAMPUS_BBOX.south],
  [CAMPUS_BBOX.east, CAMPUS_BBOX.south],
  [CAMPUS_BBOX.east, CAMPUS_BBOX.north],
  [CAMPUS_BBOX.west, CAMPUS_BBOX.north],
  [CAMPUS_BBOX.west, CAMPUS_BBOX.south],
];

/** Footprint areas of mission buildings that should glow (small boxes around each building). */
export const MISSION_BUILDINGS: { name: string; polygon: LngLat[] }[] = [
