/**
 * Fog of war: revealed H3 cells, persisted on the device, rendered as ONE polygon
 * (London boundary with explored holes) — never thousands of hexes (Constitution V).
 */
import { cellsToMultiPolygon, gridDisk, latLngToCell, polygonToCells } from "h3-js";
import type { Feature, FeatureCollection, MultiLineString, Polygon } from "geojson";
import { CAMPUS_CENTER, LONDON_BOUNDARY, type LngLat } from "./geo";

export const H3_RES = 10;
const STORAGE_KEY = "mc.cells.v1";

export const RANKS = [
  { name: "Frosh", min: 0 },
  { name: "Local", min: 1000 },
  { name: "Made", min: 5000 },
  { name: "Legend of Forest State", min: 15000 },
] as const;

export type FogSnapshot = { count: number; pct: number; rep: number; rank: string };

let cells = new Set<string>();
let loaded = false;
let londonCells: Set<string> | null = null;
let snapshot: FogSnapshot = { count: 0, pct: 0, rep: 0, rank: "Frosh" };
const listeners = new Set<() => void>();
let persistTimer: ReturnType<typeof setTimeout> | undefined;

function london() {
  if (!londonCells) londonCells = new Set(polygonToCells(LONDON_BOUNDARY, H3_RES, true));
  return londonCells;
}

function defaultCells() {
  const [lng, lat] = CAMPUS_CENTER;
  return gridDisk(latLngToCell(lat, lng, H3_RES), 2);
}

function ensureLoaded() {
  if (loaded || typeof window === "undefined") return;
  loaded = true;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    const saved: unknown = raw ? JSON.parse(raw) : null;
    cells = new Set(Array.isArray(saved) && saved.length ? (saved as string[]) : defaultCells());
  } catch {
    cells = new Set(defaultCells());
  }
  recompute();
}

function recompute() {
  const count = cells.size;
  const rep = count; // 1 Rep per cleared cell (brief → Progression)
  const rank = [...RANKS].reverse().find((r) => rep >= r.min)?.name ?? "Frosh";
  snapshot = { count, pct: (count / london().size) * 100, rep, rank };
}

function changed() {
  recompute();
  listeners.forEach((l) => l());
  clearTimeout(persistTimer);
  persistTimer = setTimeout(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify([...cells]));
    } catch {
      /* storage full / private mode — fog still works this session */
    }
  }, 500);
}

export function subscribe(listener: () => void) {
  ensureLoaded();
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function getSnapshot() {
  ensureLoaded();
  return snapshot;
}

const SERVER_SNAPSHOT: FogSnapshot = { count: 0, pct: 0, rep: 0, rank: "Frosh" };
export const getServerSnapshot = () => SERVER_SNAPSHOT;

/** Reveal the cell at a position plus its ring-1 neighbours. Returns number of new cells. */
export function revealAt(lat: number, lng: number) {
  ensureLoaded();
  const inLondon = london();
  let added = 0;
  for (const c of gridDisk(latLngToCell(lat, lng, H3_RES), 1)) {
    if (inLondon.has(c) && !cells.has(c)) {
      cells.add(c);
      added++;
    }
  }
  if (added) changed();
  return added;
}

export function resetFog() {
  ensureLoaded();
  cells = new Set(defaultCells());
  changed();
}

/** Build the fog layer data and the soft-edge lines from the revealed cells. */
export function buildFog(): { fog: FeatureCollection<Polygon>; edges: Feature<MultiLineString> } {
  ensureLoaded();
  const regions = cells.size ? cellsToMultiPolygon([...cells], true) : [];
  const holes: LngLat[][] = [];
  const islands: Feature<Polygon>[] = [];
  const edgeLines: LngLat[][] = [];

  for (const region of regions) {
    const [outer, ...inner] = region as LngLat[][];
    holes.push(outer);
    edgeLines.push(outer);
    for (const loop of inner) {
      // Unexplored pocket fully surrounded by explored cells — still fogged.
      islands.push({ type: "Feature", properties: {}, geometry: { type: "Polygon", coordinates: [loop] } });
      edgeLines.push(loop);
    }
  }

  return {
    fog: {
      type: "FeatureCollection",
      features: [
        { type: "Feature", properties: {}, geometry: { type: "Polygon", coordinates: [LONDON_BOUNDARY, ...holes] } },
        ...islands,
      ],
    },
    edges: { type: "Feature", properties: {}, geometry: { type: "MultiLineString", coordinates: edgeLines } },
  };
}

/**
 * Live location → fog reveal. Fixes stay out of React state (Constitution V).
 * Drops fixes with accuracy worse than 50 m or implying impossible speed.
 */
import { distanceM, type LngLat } from "./geo";
import { revealAt } from "./fog";

const MAX_ACCURACY_M = 50;
const MAX_SPEED_MS = 45;

export type LocationStatus = "idle" | "watching" | "denied" | "unavailable";
type Fix = { lngLat: LngLat; heading: number | null; ts: number };

let watchId: number | null = null;
let last: Fix | null = null;
let status: LocationStatus = "idle";
const fixListeners = new Set<(fix: Fix) => void>();
const statusListeners = new Set<() => void>();

function setStatus(s: LocationStatus) {
  status = s;
  statusListeners.forEach((l) => l());
}

export const getLocationStatus = () => status;
export const getServerLocationStatus = (): LocationStatus => "idle";
export function subscribeLocationStatus(l: () => void) {
  statusListeners.add(l);
  return () => statusListeners.delete(l);
}

/** Subscribe to accepted fixes (map uses this for the player dot). */
export function onFix(l: (fix: Fix) => void) {
  fixListeners.add(l);
  return () => fixListeners.delete(l);
}

/** Push a fix through the same pipeline as GPS (used by live GPS and the demo walk). */
export function acceptFix(lngLat: LngLat, heading: number | null = null, ts = Date.now()) {
  const fix = { lngLat, heading, ts };
  last = fix;
  revealAt(lngLat[1], lngLat[0]);
  fixListeners.forEach((l) => l(fix));
}

export function startWatching() {
  if (watchId !== null) return;
  if (typeof navigator === "undefined" || !("geolocation" in navigator)) return setStatus("unavailable");
  setStatus("watching");
  watchId = navigator.geolocation.watchPosition(
    (pos) => {
      const { latitude, longitude, accuracy, heading } = pos.coords;
      if (accuracy > MAX_ACCURACY_M) return;
      const lngLat: LngLat = [longitude, latitude];
      if (last) {
        const dt = (pos.timestamp - last.ts) / 1000;
        if (dt > 0 && distanceM(last.lngLat, lngLat) / dt > MAX_SPEED_MS) return;
      }
      acceptFix(lngLat, heading, pos.timestamp);
    },
    (err) => {
      stopWatching();
      setStatus(err.code === err.PERMISSION_DENIED ? "denied" : "unavailable");
    },
    { enableHighAccuracy: true, maximumAge: 2000, timeout: 20000 },
  );
}

export function stopWatching() {
  if (watchId !== null) navigator.geolocation.clearWatch(watchId);
  watchId = null;
}

"use client";

import "mapbox-gl/dist/mapbox-gl.css";
import { useEffect, useImperativeHandle, useRef, type Ref } from "react";
import type { Map as MapboxMap, GeoJSONSource } from "mapbox-gl";
import { buildFog, subscribe } from "@/lib/fog";
import { onFix } from "@/lib/location";
import { CAMPUS_CENTER, CAMPUS_POLYGON, LONDON_CENTER, MISSION_BUILDINGS, inCampus, type LngLat } from "@/lib/geo";
import { ATMOSPHERE, CAMPUS_PITCH, CAMPUS_ZOOM, CITY_PITCH, basemapConfig, londonLightPreset } from "@/lib/mapStyle";

export type MapHandle = {
  flyToCampus: () => void;
  flyToCity: () => void;
  center: () => LngLat | null;
  follow: (lngLat: LngLat) => void;
};

type Props = {
  ref?: Ref<MapHandle>;
  onReady: () => void;
  onUnavailable: (reason: string) => void;
};

const reducedMotion = () =>
  typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
const dur = (ms: number) => (reducedMotion() ? 0 : ms);

const polygon = (ring: LngLat[]) => ({ type: "Polygon" as const, coordinates: [ring] });

function addGameLayers(map: MapboxMap) {
  // --- Campus 3D buildings (Mustang City) -----------------------------------
  map.addSource("streets", { type: "vector", url: "mapbox://mapbox.mapbox-streets-v8" });
  map.addLayer({
    id: "campus-buildings",
    type: "fill-extrusion",
    source: "streets",
    "source-layer": "building",
    slot: "middle",
    minzoom: 14.5,
    filter: ["within", polygon(CAMPUS_POLYGON)],
    paint: {
      "fill-extrusion-color": [
        "interpolate", ["linear"], ["coalesce", ["get", "height"], 10],
        0, "#7b2ff7",
        20, "#c13dd6",
        45, "#ff4f8b",
      ],
      "fill-extrusion-height": ["+", ["coalesce", ["get", "height"], 10], 1.5],
      "fill-extrusion-base": ["coalesce", ["get", "min_height"], 0],
      "fill-extrusion-opacity": ["interpolate", ["linear"], ["zoom"], 14.5, 0, 15.5, 0.92],
      "fill-extrusion-vertical-gradient": true,
      "fill-extrusion-emissive-strength": 0.7,
    },
  });
  map.addLayer({
    id: "mission-buildings",
    type: "fill-extrusion",
    source: "streets",
    "source-layer": "building",
    slot: "middle",
    minzoom: 14.5,
    filter: ["any", ...MISSION_BUILDINGS.map((b) => ["within", polygon(b.polygon)])],
    paint: {
      "fill-extrusion-color": "#ffc857",
      "fill-extrusion-height": ["+", ["coalesce", ["get", "height"], 12], 3],
      "fill-extrusion-base": ["coalesce", ["get", "min_height"], 0],
      "fill-extrusion-opacity": ["interpolate", ["linear"], ["zoom"], 14.5, 0, 15.5, 1],
      "fill-extrusion-emissive-strength": 1,
    },
  });

  // --- Fog of war -------------------------------------------------------------
  const { fog, edges } = buildFog();
  map.addSource("fog", { type: "geojson", data: fog });
  map.addSource("fog-edges", { type: "geojson", data: edges });
  map.addLayer({
    id: "fog-fill",
    type: "fill",
    source: "fog",
    slot: "top",
    paint: { "fill-color": "#000000", "fill-opacity": 0.97, "fill-emissive-strength": 1 },
  });
  map.addLayer({
    id: "fog-edge",
    type: "line",
    source: "fog-edges",
    slot: "top",
    layout: { "line-join": "round" },
    paint: {
      "line-color": "#000000",
      "line-opacity": 0.85,
      "line-width": ["interpolate", ["exponential", 2], ["zoom"], 11, 4, 16, 48],
      "line-blur": ["interpolate", ["exponential", 2], ["zoom"], 11, 4, 16, 48],
      "line-emissive-strength": 1,
    },
  });

  // --- Player -----------------------------------------------------------------
  map.addSource("player", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
  map.addLayer({
    id: "player-halo",
    type: "circle",
    source: "player",
    slot: "top",
    paint: {
      "circle-radius": 20,
      "circle-color": "#2ee6d6",
      "circle-opacity": 0.22,
      "circle-pitch-alignment": "map",
      "circle-emissive-strength": 1,
    },
  });
  map.addLayer({
    id: "player-dot",
    type: "circle",
    source: "player",
    slot: "top",
    paint: {
      "circle-radius": 7,
      "circle-color": "#2ee6d6",
      "circle-stroke-color": "#ffffff",
      "circle-stroke-width": 2,
      "circle-pitch-alignment": "map",
      "circle-emissive-strength": 1,
    },
  });
}

export default function MapView({ ref, onReady, onUnavailable }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<MapboxMap | null>(null);
  const callbacks = useRef({ onReady, onUnavailable });

  useEffect(() => {
    callbacks.current = { onReady, onUnavailable };
  });

  useImperativeHandle(ref, () => ({
    flyToCampus: () =>
      mapRef.current?.flyTo({ center: CAMPUS_CENTER, zoom: 16.2, pitch: CAMPUS_PITCH, bearing: -30, duration: dur(2200), essential: true }),
    flyToCity: () =>
      mapRef.current?.flyTo({ center: LONDON_CENTER, zoom: 12, pitch: CITY_PITCH, bearing: -15, duration: dur(2200), essential: true }),
    center: () => {
      const c = mapRef.current?.getCenter();
      return c ? [c.lng, c.lat] : null;
    },
    follow: (lngLat) => mapRef.current?.easeTo({ center: lngLat, duration: dur(400), essential: true }),
  }));

  useEffect(() => {
    const token = process.env.NEXT_PUBLIC_MAPBOX_TOKEN;
    if (!token) {
      callbacks.current.onUnavailable("missing-token");
      return;
    }
    let cancelled = false;
    const cleanups: (() => void)[] = [];

    import("mapbox-gl").then(({ default: mapboxgl }) => {
      if (cancelled || !containerRef.current) return;
      if (!mapboxgl.supported?.() && "supported" in mapboxgl) {
        callbacks.current.onUnavailable("webgl");
        return;
      }
      mapboxgl.accessToken = REDACTED;
      const map = new mapboxgl.Map({
        container: containerRef.current,
        style: "mapbox://styles/mapbox/standard",
        config: { basemap: basemapConfig(londonLightPreset()) },
        center: CAMPUS_CENTER,
        zoom: 13.4,
        pitch: CITY_PITCH,
        bearing: -20,
        maxPitch: 70,
        minZoom: 10,
        attributionControl: false,
        pixelRatio: Math.min(window.devicePixelRatio || 1, 2),
      });
      mapRef.current = map;
      map.addControl(new mapboxgl.AttributionControl({ compact: true }), "bottom-right");

      map.on("style.load", () => {
        map.setFog(ATMOSPHERE);
        addGameLayers(map);
      });
      map.once("idle", () => callbacks.current.onReady());
      map.on("error", (e) => {
        const status = (e.error as { status?: number } | undefined)?.status;
        if (status === 401 || status === 403) callbacks.current.onUnavailable("bad-token");
      });

      // Camera mode: city (45°) ↔ Mustang City (60°), switched only on mode change.
      let mode: "city" | "campus" = "city";
      map.on("moveend", () => {
        const c = map.getCenter();
        const next = map.getZoom() >= CAMPUS_ZOOM && inCampus([c.lng, c.lat]) ? "campus" : "city";
        if (next === mode) return;
        mode = next;
        map.easeTo({ pitch: next === "campus" ? CAMPUS_PITCH : CITY_PITCH, duration: dur(900), essential: true });
      });

      // Fog: rebuild only when cells change, debounced.
      let fogTimer: ReturnType<typeof setTimeout> | undefined;
      cleanups.push(
        subscribe(() => {
          clearTimeout(fogTimer);
          fogTimer = setTimeout(() => {
            if (!map.getSource("fog")) return;
            const { fog, edges } = buildFog();
            (map.getSource("fog") as GeoJSONSource).setData(fog);
            (map.getSource("fog-edges") as GeoJSONSource).setData(edges);
          }, 150);
        }),
      );

      cleanups.push(
        onFix(({ lngLat }) => {
          (map.getSource("player") as GeoJSONSource | undefined)?.setData({
            type: "Feature",
            properties: {},
            geometry: { type: "Point", coordinates: lngLat },
          });
        }),
      );

      const ro = new ResizeObserver(() => map.resize());
      ro.observe(containerRef.current);
      cleanups.push(() => ro.disconnect());
    });

    return () => {
      cancelled = true;
      cleanups.forEach((c) => c());
      mapRef.current?.remove();
      mapRef.current = null;
    };
  }, []);

  return <div ref={containerRef} className="absolute inset-0" />;
}

