import { Auth0Client } from "@auth0/nextjs-auth0/server";
import { NextResponse } from "next/server";

const { AUTH0_DOMAIN, AUTH0_CLIENT_ID, AUTH0_CLIENT_SECRET, AUTH0_SECRET, APP_BASE_URL } = process.env;

export const isUwoEmail = (email?: string | null) => !!email && email.toLowerCase().endsWith("@uwo.ca");

/**
 * Auth0 client, or null when this deployment has no Auth0 config (the app keeps working
 * without sign-in — Constitution IV). The primary @uwo.ca gate is the Auth0 Login Action in
 * auth0/uwo-only-action.js; this callback re-checks in case the Action is missing.
 */
export const auth0 =
  AUTH0_DOMAIN && AUTH0_CLIENT_ID && AUTH0_CLIENT_SECRET && AUTH0_SECRET
    ? new Auth0Client({
        domain: AUTH0_DOMAIN,
        clientId: AUTH0_CLIENT_ID,
        clientSecret: AUTH0_CLIENT_SECRET,
        secret: AUTH0_SECRET,
        appBaseUrl: APP_BASE_URL,
        authorizationParameters: { scope: "openid profile email" },
        async onCallback(error, ctx, session) {
          const base = APP_BASE_URL ?? "";
          if (error) return NextResponse.redirect(new URL("/?denied=uwo", base));
          if (session && !isUwoEmail(session.user.email)) {
            const returnTo = new URL("/?denied=uwo", base).toString();
            return NextResponse.redirect(new URL(`/auth/logout?returnTo=${encodeURIComponent(returnTo)}`, base));
          }
          return NextResponse.redirect(new URL(ctx.returnTo ?? "/", base));
        },
      })
    : null;

import { NextResponse, type NextRequest } from "next/server";
import { auth0 } from "@/lib/auth0";

export async function proxy(request: NextRequest) {
  if (!auth0) return NextResponse.next();
  return auth0.middleware(request);
}

export const config = {
  matcher: ["/auth/:path*"],
};

/**
 * Auth0 Action — Login / Post Login flow.
 * Auth0 Dashboard → Actions → Library → Create Action (Login / Post Login),
 * paste this, Deploy, then drag it into Actions → Triggers → post-login.
 *
 * Only Western (@uwo.ca) accounts may sign in to Mustang City.
 */
exports.onExecutePostLogin = async (event, api) => {
  const email = (event.user.email || "").toLowerCase();
  if (!email.endsWith("@uwo.ca")) {
    api.access.deny("Only @uwo.ca accounts can sign in to Mustang City.");
  }
};

