/**
 * Live location. Fixes stay out of React state (Constitution V).
 *
 * - Every fix moves the player marker (with an accuracy circle), however rough.
 * - Only fixes accurate to REVEAL_ACCURACY_M clear fog, and never ones implying impossible speed.
 * - Heading comes from the compass when available (iOS asks permission on the same tap),
 *   else GPS course, else direction of travel; null means "unknown" (marker shows a dot).
 */
import { bearing, distanceM, type LngLat } from "./geo";
import { revealAround } from "./fog";

export const REVEAL_ACCURACY_M = 50;
const MAX_SPEED_MS = 45;

export type LocationStatus = "idle" | "locating" | "watching" | "denied" | "unavailable";
export type Fix = { lngLat: LngLat; heading: number | null; accuracy: number; ts: number };
export type LocationState = { status: LocationStatus; accuracy: number | null };

let watchId: number | null = null;
let current: Fix | null = null; // latest position shown on the map
let lastRevealed: Fix | null = null; // latest position that cleared fog (speed check)
let compassHeading: number | null = null;
let state: LocationState = { status: "idle", accuracy: null };
const fixListeners = new Set<(fix: Fix, first: boolean) => void>();
const stateListeners = new Set<() => void>();

function setState(next: Partial<LocationState>) {
  const merged = { ...state, ...next };
  if (merged.status === state.status && merged.accuracy === state.accuracy) return;
  state = merged;
  stateListeners.forEach((l) => l());
}

export const getLocationState = () => state;
const SERVER_STATE: LocationState = { status: "idle", accuracy: null };
export const getServerLocationState = () => SERVER_STATE;
export function subscribeLocationState(l: () => void) {
  stateListeners.add(l);
  return () => stateListeners.delete(l);
}

/** Subscribe to position/heading updates. `first` is true for the first fix of a session. */
export function onFix(l: (fix: Fix, first: boolean) => void) {
  fixListeners.add(l);
  return () => fixListeners.delete(l);
}

export const getLastFix = () => current;

function emit(fix: Fix, first: boolean) {
  fixListeners.forEach((l) => l(fix, first));
}

/**
 * Push a position through the same pipeline as GPS (live GPS and the demo walk both use this).
 * Returns true if it cleared fog.
 */
export function acceptFix(lngLat: LngLat, opts: { accuracy?: number; course?: number | null; ts?: number } = {}) {
  const { accuracy = 5, course = null, ts = Date.now() } = opts;
  const prev = current;

  let heading: number | null = compassHeading;
  if (heading === null && course !== null && !Number.isNaN(course)) heading = course;
  if (heading === null && prev) {
    heading = distanceM(prev.lngLat, lngLat) > 4 ? bearing(prev.lngLat, lngLat) : prev.heading;
  }

  const fix: Fix = { lngLat, heading, accuracy, ts };
  current = fix;
  setState({ status: "watching", accuracy: Math.round(accuracy) });

  let revealed = false;
  if (accuracy <= REVEAL_ACCURACY_M) {
    const dt = lastRevealed ? (ts - lastRevealed.ts) / 1000 : Infinity;
    const tooFast = lastRevealed && dt > 0 && dt < 120 && distanceM(lastRevealed.lngLat, lngLat) / dt > MAX_SPEED_MS;
    if (!tooFast) {
      revealAround(lngLat[1], lngLat[0]);
      lastRevealed = fix;
      revealed = true;
    }
  }
  emit(fix, !prev);
  return revealed;
}

// ---- Compass ---------------------------------------------------------------------
let lastCompassEmit = 0;
function onOrientation(e: DeviceOrientationEvent) {
  const webkit = (e as DeviceOrientationEvent & { webkitCompassHeading?: number }).webkitCompassHeading;
  const h = typeof webkit === "number" ? webkit : e.absolute && e.alpha !== null ? (360 - e.alpha) % 360 : null;
  if (h === null) return;
  compassHeading = h;
  const now = performance.now();
  if (current && now - lastCompassEmit > 100) {
    lastCompassEmit = now;
    current = { ...current, heading: h };
    emit(current, false);
  }
}

async function startCompass() {
  if (typeof window === "undefined" || !("DeviceOrientationEvent" in window)) return;
  const DOE = DeviceOrientationEvent as unknown as { requestPermission?: () => Promise<string> };
  try {
    // iOS 13+: must be requested from a user gesture (the Enable / locate tap).
    if (typeof DOE.requestPermission === "function" && (await DOE.requestPermission()) !== "granted") return;
  } catch {
    return;
  }
  window.addEventListener("deviceorientationabsolute" as "deviceorientation", onOrientation);
  window.addEventListener("deviceorientation", onOrientation);
}

// ---- GPS -------------------------------------------------------------------------
export function startWatching() {
  if (watchId !== null) return;
  if (typeof navigator === "undefined" || !("geolocation" in navigator)) return setState({ status: "unavailable" });
  void startCompass();
  setState({ status: current ? "watching" : "locating" });
  watchId = navigator.geolocation.watchPosition(
    (pos) => {
      const { latitude, longitude, accuracy, heading, speed } = pos.coords;
      const course = heading !== null && (speed ?? 0) > 0.5 ? heading : null;
      acceptFix([longitude, latitude], { accuracy, course, ts: pos.timestamp });
    },
    (err) => {
      // Timeouts / temporary signal loss: keep watching, the next fix will come.
      if (err.code === err.PERMISSION_DENIED) {
        stopWatching();
        setState({ status: "denied" });
      } else if (!current) {
        setState({ status: "locating" });
      }
    },
    { enableHighAccuracy: true, maximumAge: 0, timeout: 30000 },
  );
}

export function stopWatching() {
  if (watchId !== null) navigator.geolocation.clearWatch(watchId);
  watchId = null;
}

/**
 * Fog of war: revealed H3 cells, persisted on the device, rendered as ONE polygon
 * (London boundary with explored holes) — never thousands of hexes (Constitution V).
 *
 * Resolution 11 (~25 m cells) so the cleared area around the player reads as a circle:
 * every cell whose centre lies within REVEAL_RADIUS_M of an accepted fix is revealed.
 */
import { cellToChildren, cellToLatLng, cellsToMultiPolygon, gridDisk, latLngToCell, polygonToCells } from "h3-js";
import type { Feature, FeatureCollection, MultiLineString, Polygon } from "geojson";
import { CAMPUS_CENTER, LONDON_BOUNDARY, distanceM, type LngLat } from "./geo";

export const H3_RES = 11;
export const REVEAL_RADIUS_M = 100;
const RING_K = 5; // res-11 centre spacing ≈ 43 m, so k=5 safely covers a 100 m radius
const STORAGE_KEY = "mc.cells.v2";
const LEGACY_KEY = "mc.cells.v1"; // res 10

export const RANKS = [
  { name: "Frosh", min: 0 },
  { name: "Local", min: 1000 },
  { name: "Made", min: 5000 },
  { name: "Legend of Forest State", min: 15000 },
] as const;

export type FogSnapshot = { count: number; pct: number; rep: number; rank: string };

let cells = new Set<string>();
let loaded = false;
let londonCellCount = 0;
let snapshot: FogSnapshot = { count: 0, pct: 0, rep: 0, rank: "Frosh" };
const listeners = new Set<() => void>();
let persistTimer: ReturnType<typeof setTimeout> | undefined;

function pointInLondon([x, y]: LngLat) {
  const ring = LONDON_BOUNDARY;
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

/** London measured in res-11 cells (res-9 count × 49 children — cheap and accurate enough). */
function londonCells() {
  if (!londonCellCount) londonCellCount = polygonToCells(LONDON_BOUNDARY, 9, true).length * 49;
  return londonCellCount;
}

function cellsAround(lat: number, lng: number, radiusM: number) {
  const out: string[] = [];
  for (const c of gridDisk(latLngToCell(lat, lng, H3_RES), RING_K)) {
    const [clat, clng] = cellToLatLng(c);
    if (distanceM([lng, lat], [clng, clat]) <= radiusM && pointInLondon([clng, clat])) out.push(c);
  }
  return out;
}

function defaultCells() {
  const [lng, lat] = CAMPUS_CENTER;
  return cellsAround(lat, lng, 150);
}

function ensureLoaded() {
  if (loaded || typeof window === "undefined") return;
  loaded = true;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    const saved: unknown = raw ? JSON.parse(raw) : null;
    if (Array.isArray(saved) && saved.length) {
      cells = new Set(saved as string[]);
    } else {
      // Migrate res-10 cells from the first build: each becomes its 7 res-11 children.
      const legacy: unknown = JSON.parse(localStorage.getItem(LEGACY_KEY) ?? "null");
      cells = new Set(Array.isArray(legacy) && legacy.length ? (legacy as string[]).flatMap((c) => cellToChildren(c, H3_RES)) : defaultCells());
    }
  } catch {
    cells = new Set(defaultCells());
  }
  recompute();
}

function recompute() {
  const count = cells.size;
  const rep = Math.floor(count / 7); // ≈ 1 Rep per brief-sized (res-10) cell cleared
  const rank = [...RANKS].reverse().find((r) => rep >= r.min)?.name ?? "Frosh";
  snapshot = { count, pct: (count / londonCells()) * 100, rep, rank };
}

function changed() {
  recompute();
  listeners.forEach((l) => l());
  clearTimeout(persistTimer);
  persistTimer = setTimeout(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify([...cells]));
    } catch {
      /* storage full / private mode — fog still works this session */
    }
  }, 500);
}

export function subscribe(listener: () => void) {
  ensureLoaded();
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function getSnapshot() {
  ensureLoaded();
  return snapshot;
}

const SERVER_SNAPSHOT: FogSnapshot = { count: 0, pct: 0, rep: 0, rank: "Frosh" };
export const getServerSnapshot = () => SERVER_SNAPSHOT;

/** Clear fog within `radiusM` of a position. Returns the number of newly revealed cells. */
export function revealAround(lat: number, lng: number, radiusM = REVEAL_RADIUS_M) {
  ensureLoaded();
  let added = 0;
  for (const c of cellsAround(lat, lng, radiusM)) {
    if (!cells.has(c)) {
      cells.add(c);
      added++;
    }
  }
  if (added) changed();
  return added;
}

export function isRevealedAt(lat: number, lng: number) {
  ensureLoaded();
  return cells.has(latLngToCell(lat, lng, H3_RES));
}

export function resetFog() {
  ensureLoaded();
  cells = new Set(defaultCells());
  changed();
}

/** Build the fog layer data and the soft-edge lines from the revealed cells. */
export function buildFog(): { fog: FeatureCollection<Polygon>; edges: Feature<MultiLineString> } {
  ensureLoaded();
  const regions = cells.size ? cellsToMultiPolygon([...cells], true) : [];
  const holes: LngLat[][] = [];
  const islands: Feature<Polygon>[] = [];
  const edgeLines: LngLat[][] = [];

  for (const region of regions) {
    const [outer, ...inner] = region as LngLat[][];
    holes.push(outer);
    edgeLines.push(outer);
    for (const loop of inner) {
      // Unexplored pocket fully surrounded by explored cells — still fogged.
      islands.push({ type: "Feature", properties: {}, geometry: { type: "Polygon", coordinates: [loop] } });
      edgeLines.push(loop);
    }
  }

  return {
    fog: {
      type: "FeatureCollection",
      features: [
        { type: "Feature", properties: {}, geometry: { type: "Polygon", coordinates: [LONDON_BOUNDARY, ...holes] } },
        ...islands,
      ],
    },
    edges: { type: "Feature", properties: {}, geometry: { type: "MultiLineString", coordinates: edgeLines } },
  };
}

