  ctx.arc(size / 2, size / 2, 11, 0, Math.PI * 2);
  ctx.fillStyle = "#2ee6d6";
  ctx.fill();
  ctx.shadowBlur = 0;
  ctx.lineWidth = 4;
  ctx.strokeStyle = "#ffffff";
  ctx.stroke();
  return ctx.getImageData(0, 0, size, size);
}

